let mine=[],storageBroken=false;
try{const stored=JSON.parse(localStorage.getItem(key)||"[]");if(Array.isArray(stored))mine=stored.filter(s=>s&&typeof s.id==="string"&&typeof s.alias==="string"&&s.alias.length<=32&&typeof s.message==="string"&&s.message.length<=180&&/^\d{4}-\d{2}-\d{2}$/.test(s.date)&&Number.isFinite(s.x)&&s.x>=10&&s.x<=90&&Number.isFinite(s.y)&&s.y>=10&&s.y<=85).map(s=>({...s,sample:false}));}catch{storageBroken=true;}
const all=()=>[...samples,...mine];let toastTimer,paused=reduced;
function toast(message){$("#toast").textContent=message;$("#toast").classList.add("visible");clearTimeout(toastTimer);toastTimer=setTimeout(()=>$("#toast").classList.remove("visible"),5000);}
function openStory(star){$("#story-kind").textContent=star.sample?"虚构示例星 · "+star.id.replace("example-","NO. 0"):"我的星 · 仅存于当前浏览器";$("#story-dialog-title").textContent=star.alias;$("#story-date").textContent="连接结束于 "+star.date.replaceAll("-"," / ");$("#story-message").textContent=star.message;$("#story-caption").textContent=star.sample?"此名字、日期与留言均为虚构示例。":"这句告别已保存在当前浏览器，未上传到服务器。";$("#story-dialog").showModal();}
function render(){const nodes=$("#star-nodes");nodes.replaceChildren();all().forEach((s,i)=>{const b=document.createElement("button");b.type="button";b.className="star-node"+(i===7?" star-node--featured":"")+(!s.sample?" star-node--mine":"");b.style.setProperty("--x",s.x);b.style.setProperty("--y",s.y);b.dataset.starId=s.id;b.setAttribute("aria-label",(s.sample?"示例星：":"我的星：")+s.alias+"，阅读留言");const name=document.createElement("span");name.className="star-node__name";name.textContent=s.alias;const tag=document.createElement("span");tag.className="star-node__tag";tag.textContent=s.sample?"示例星":"我的星";name.append(tag);b.append(name);b.addEventListener("click",()=>openStory(s));nodes.append(b);});$("#my-count").textContent=mine.length;const svg=$("#constellations");svg.replaceChildren();[[0,1],[1,2],[2,4],[4,5],[5,3],[3,0],[3,7],[7,2],[6,3]].forEach(([a,b])=>{const l=document.createElementNS("http://www.w3.org/2000/svg","line");for(const [k,v]of Object.entries({x1:samples[a].x,y1:samples[a].y,x2:samples[b].x,y2:samples[b].y}))l.setAttribute(k,v);svg.append(l);});}
const list=$("#story-list");samples.forEach((s,i)=>{const b=document.createElement("button");b.type="button";b.className="story-row";for(const [cls,txt]of [["number","0"+(i+1)],["alias",s.alias],["meta","虚构示例 · "+s.date.slice(5).replace("-"," / ")],["arrow","↗"]]){const el=document.createElement("span");el.className="story-row__"+cls;el.textContent=txt;b.append(el);}b.addEventListener("click",()=>openStory(s));list.append(b);});
function today(){const d=new Date();return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,10);}
document.querySelectorAll("[data-open-new]").forEach(b=>b.onclick=()=>{$("#form-error").textContent="";$("#star-date").value=today();$("#star-date").max=today();$("#new-star-dialog").showModal();});document.querySelectorAll("[data-open-about]").forEach(b=>b.onclick=()=>$("#about-dialog").showModal());
document.querySelectorAll("dialog").forEach(d=>d.addEventListener("click",e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));
$("#random-star").onclick=()=>{const stars=all();openStory(stars[Math.floor(Math.random()*stars.length)]);};
$("#toggle-lines").onclick=()=>{const off=$("#atlas").classList.toggle("lines-hidden");$("#toggle-lines").setAttribute("aria-pressed",String(!off));};
function updatePause(){document.body.classList.toggle("motion-paused",paused);$("#pause-motion").setAttribute("aria-pressed",String(paused));$("#pause-motion").textContent=paused?"继续星图":"暂停星图";}
$("#pause-motion").onclick=()=>{paused=!paused;updatePause();};updatePause();
$("#new-star-form").onsubmit=async e=>{e.preventDefault();const alias=$("#star-alias").value.trim(),date=$("#star-date").value,message=$("#star-message").value.trim();if(!alias||!date||!message||date>today()){$("#form-error").textContent="请留下别名、有效的停用日期（不晚于今天）和一句话。";return;}const s={id:"star-"+crypto.randomUUID(),alias,date,message,x:15+Math.random()*68,y:18+Math.random()*62,sample:false};try{localStorage.setItem(key,JSON.stringify([...mine,s]));storageBroken=false;}catch{$("#form-error").textContent="浏览器暂时无法保存，请允许网站存储后再试。你的文字还在。";return;}mine.push(s);render();$("#new-star-dialog").close();e.target.reset();window.scrollTo({top:0,behavior:reduced?"instant":"smooth"});toast("这句告别，正在成为一颗星。");if(!reduced){await new Promise(r=>setTimeout(r,450));const target=[...document.querySelectorAll(".star-node")].find(b=>b.dataset.starId===s.id);target.scrollIntoView({block:"center",behavior:"instant"});const r=target.getBoundingClientRect(),spark=document.createElement("div");spark.className="rising-star";const words=document.createElement("span");words.textContent=message;spark.append(words);document.body.append(spark);const dx=r.left+r.width/2-innerWidth*.5,dy=r.top+r.height/2-innerHeight*.82;words.animate([{opacity:1},{opacity:0}],{duration:1300,fill:"forwards"});await spark.animate([{transform:"translate(0,0) scale(1)",opacity:1},{transform:`translate(${dx*.4}px,${dy*.5}px) scale(.7)`,opacity:1,offset:.55},{transform:`translate(${dx}px,${dy}px) scale(.3)`,opacity:0}],{duration:2400,easing:"cubic-bezier(.2,.6,.2,1)",fill:"forwards"}).finished;spark.remove();}toast("你的星已升起，并保存在当前浏览器。");openStory(s);};
render();if(storageBroken)toast("旧记录暂时无法读取，你仍可以浏览示例星。");
const canvas=$("#sky"),ctx=canvas.getContext("2d");let w=0,h=0,stars=[],last=0,t=0;function resize(){w=innerWidth;h=innerHeight;const d=Math.min(devicePixelRatio||1,2);canvas.width=w*d;canvas.height=h*d;ctx.setTransform(d,0,0,d,0,0);stars=Array.from({length:Math.min(700,Math.floor(w*h/1800))},()=>({x:Math.random()*w,y:Math.random()*h,r:Math.random()*1.1+.2,p:Math.random()*6.28,a:Math.random()*.65+.15}));}function draw(now){requestAnimationFrame(draw);if(document.hidden||now-last<40)return;last=now;if(!paused)t+=.014;ctx.clearRect(0,0,w,h);const glow=ctx.createRadialGradient(w*.72,h*.38,0,w*.72,h*.38,w*.45);glow.addColorStop(0,"rgba(60,100,127,.13)");glow.addColorStop(.5,"rgba(32,66,96,.05)");glow.addColorStop(1,"transparent");ctx.fillStyle=glow;ctx.fillRect(0,0,w,h);for(const s of stars){ctx.globalAlpha=s.a*(.72+.28*Math.sin(t+s.p));ctx.fillStyle=s.r>.95?"#e7d4b4":"#bacbdc";ctx.beginPath();ctx.arc(s.x,s.y,s.r,0,Math.PI*2);ctx.fill();}ctx.globalAlpha=1;}addEventListener("resize",resize);resize();requestAnimationFrame(draw);
